details.command:
kubectl get statefulset,svc,pvc,pv -n default -o custom='column="NAME|STATUS";kind=statefulstatus;jsonpath={.items[*].metadata.name},{.items[*].status.readyReplicas}/{.items[*].spec.replicas}
|{.items[*].metadata.name}.serviceType: {range .items[?(@.metadata.name=="app")].status.conditions[]|select(.type=="Available")|.status}
{range .items[?(@.metadata.name!="app")]};empty
' 2>/dev/null || kubectl get statefulset app,svc -n default && kubectl get pvc,pv -n default -o wide | head -10
